from lib import *
S = SS('n48')
steps = [
    step("Run、RunTLS、RunUnix、RunListener 都是同一个模式:新建 http.Server{Handler: engine.Handler()}(带 #nosec G112,没有任何超时),再 Serve / ListenAndServeTLS。Handler() 默认直接返回 engine;只有 UseH2C=true 才用 h2c.NewHandler(engine, &http2.Server{}) 包一层。HTTPS 下的 HTTP/2 不是 Gin 做的,是标准库 ListenAndServeTLS 自动启用的。", t=tl(S(1)), mark=lidx(S(1), 'h2c.NewHandler(engine, h2s)', 'server.ListenAndServeTLS(certFile, keyFile)', '#nosec G112'), done=lidx(S(1), 'if !engine.UseH2C {', 'Handler: engine.Handler()'), kv=KV([['Handler()', '默认就是 engine;UseH2C 才套 h2c'], ['RunTLS', 'ListenAndServeTLS,HTTP/2 由标准库自动启用'], ['超时', '没有任何超时(#nosec G112)']], ['Handler()'])),
    step("明文端口:没开 UseH2C 时,curl --http1.1 得到 Proto=HTTP/1.1;curl --http2-prior-knowledge 失败(Remote peer returned unexpected data while we expected SETTINGS frame);curl --http2(带 Upgrade 头)被忽略,仍是 HTTP/1.1。开了 UseH2C:--http2-prior-knowledge 成功,handler 里 Proto=HTTP/2.0、ProtoMajor=2;同一端口 --http1.1 依然 HTTP/1.1;--http2 的 Upgrade 路径下第一个请求 handler 里仍是 HTTP/1.1(升级请求本身),之后连接才切到 HTTP/2(curl 报 [2])。", t=tl(S(2)), mark=lidx(S(2), '[plain]', 'curl --http2-prior-knowledge: [0]'), done=lidx(S(2), '[h2c]', 'Proto=HTTP/2.0 ProtoMajor=2'), kv=KV([['没开 UseH2C', '--http2-prior-knowledge 失败'], ['开了', '同端口 HTTP/1.1 与 h2c 并存'], ['Upgrade', '第一个请求仍是 HTTP/1.1']], ['没开 UseH2C'])),
    step("RunTLS(自签名 ECDSA 证书):curl -k 默认协商出 HTTP/2——handler 里 Proto=HTTP/2.0,TLS 版本 0x304(TLS 1.3),ALPN=\"h2\";--http1.1 则 ALPN=\"http/1.1\"、Proto=HTTP/1.1;TLS 1.1 被拒绝(alert protocol version,Go 默认最低 TLS 1.2);不加 -k 因证书不受信任而失败。HTTP/2 下 c.Writer.Pusher() 非 nil,但 Push 返回 feature not supported(curl 不接受推送);HTTP/1.1 下 Pusher() 为 nil;Hijack 在 HTTP/1.1 下成功,在 HTTP/2 下 panic:interface conversion: http.http2ResponseWriter is not http.Hijacker(Gin 没有检查类型断言)。", t=tl(S(3)), mark=lidx(S(3), 'tlsv1 alert protocol version', 'Hijack panic', 'Push 返回 feature not supported'), done=lidx(S(3), 'curl -k(默认)', 'curl -k --http1.1', 'Hijack 成功', 'Pusher() 为 nil'), kv=KV([['ALPN', 'h2 → HTTP/2.0;http/1.1 → HTTP/1.1'], ['TLS 版本', '最低 1.2(1.1 被拒)'], ['HTTP/2 + Hijack', 'panic,要自己 recover'], ['Push', '客户端不接受时返回 feature not supported']], ['HTTP/2 + Hijack'])),
    step("证书文件不存在时 RunTLS 立刻返回错误(服务结束:open …/nope.pem: no such file or directory),不会退化成不加密的服务。", t=tl(S(4)), mark=lidx(S(4), 'no such file or directory'), kv=KV([['证书缺失', 'RunTLS 立刻返回 error'], ['处理', '检查返回值,别忽略它']], ['证书缺失'])),
    step("RunUnix:socket 文件权限是 0755;ClientIP 对 unix socket 的连接一律信任转发头——即使 SetTrustedProxies(nil):X-Forwarded-For: 1.2.3.4 得到 ClientIP=1.2.3.4,9.9.9.9, 1.2.3.4 也是 1.2.3.4,而没有头时 RemoteAddr 是空串,ClientIP 是字面量 \"<nil>\";进程被 SIGTERM 杀死后 socket 文件仍留在磁盘上(defer os.Remove 没执行),再启动报 listen unix …: bind: address already in use。", t=tl(S(5)), mark=lidx(S(5), 'ClientIP="1.2.3.4"', 'ClientIP="<nil>"', '仍存在', 'address already in use'), done=lidx(S(5), '权限: 0o755'), kv=KV([['ClientIP', 'unix socket 一律信任转发头'], ['无头时', '"<nil>"(字面量)'], ['被信号杀死', 'socket 文件残留,下次启动报 address already in use']], ['被信号杀死'])),
]
A = mkartn('n48', 48, 'Gin,HTTP/2,h2c,RunTLS,unix socket,Go,真实验证,动画演示',
    '在 Gin v1.12.0 里实测协议与监听方式:UseH2C 开启才支持 curl --http2-prior-knowledge(同端口 HTTP/1.1 并存);RunTLS 下 curl 协商出 HTTP/2(ALPN h2,TLS 1.3),TLS 1.1 被拒;HTTP/2 下 Hijack 会 panic;证书缺失立刻返回错误;RunUnix 上 ClientIP 一律信任转发头,无头时是 "<nil>",被信号杀死会残留 socket 文件。',
    'Gin 能不能跑 HTTP/2、明文 h2c、unix socket?这篇起了真实的服务进程,用 curl 与 handler 里看到的 Proto / ALPN / TLS 版本逐项验证,并发现了 HTTP/2 下 Hijack 会 panic、unix socket 上 ClientIP 的两个怪行为。',
    [('HTTP/2.0', 'RunTLS 下 curl 默认协商出的协议(ALPN=h2,TLS 1.3)'), ('UseH2C', '打开之后 curl --http2-prior-knowledge 成功;没打开时失败'), ('"<nil>"', 'unix socket 上没有转发头时 c.ClientIP() 的返回值')],
    [('只是 http.Server', '<p>四个 <code>Run*</code> 方法都是新建一个只设了 <code>Handler</code> 的 <code>http.Server</code>。HTTPS 的 HTTP/2 是标准库 <code>ListenAndServeTLS</code> 通过 ALPN 自动启用的;明文 h2c 需要 <code>engine.UseH2C = true</code>,此时 <code>Handler()</code> 用 x/net 的 <code>h2c.NewHandler</code> 包一层,同一端口同时接受 HTTP/1.1 和 h2c。</p>'),
     ('h2c', '<p>没开 <code>UseH2C</code> 时,以 prior knowledge 方式说 HTTP/2 的客户端直接失败(服务端回的是 HTTP/1.1 的数据)。开了之后 prior knowledge 成功,<code>Request.Proto</code> 是 <code>HTTP/2.0</code>。带 <code>Upgrade: h2c</code> 的请求,第一个请求仍按 HTTP/1.1 处理,之后连接才升级。</p>'),
     ('HTTPS 与 HTTP/2 的差别', '<p>TLS 默认最低 1.2(TLS 1.1 被拒),ALPN 协商出 h2 时 handler 看到 <code>HTTP/2.0</code>。注意几个 HTTP/2 下的不同:<code>Pusher()</code> 非 nil 但客户端关闭推送时 <code>Push</code> 返回 <code>feature not supported</code>;<code>Hijack</code> 不被支持,而 Gin 的 <code>responseWriter.Hijack</code> 直接做类型断言,所以在 HTTP/2 上调用会 panic(被 <code>Recovery</code> 接住也只是 500)。依赖 Hijack 的功能(WebSocket)要么用 HTTP/1.1,要么用 HTTP/2 的扩展 CONNECT。</p>'),
     ('证书缺失', '<p><code>RunTLS</code> 找不到证书或密钥文件时立刻返回错误,不会退化成明文服务。它返回的 error 必须被检查——常见的写法 <code>r.RunTLS(...)</code> 不检查返回值时,程序会直接退出而没有任何提示。</p>'),
     ('unix socket', '<p><code>RunUnix</code> 对 unix socket 上的连接一律信任转发头,不管 <code>SetTrustedProxies</code> 怎么设(设计上假设 socket 后面是本机的反向代理)。注意没有转发头时 <code>RemoteAddr</code> 是空串,<code>ClientIP()</code> 会返回字面量 <code>"&lt;nil&gt;"</code>。socket 文件在正常返回时由 <code>defer os.Remove</code> 删除,进程被信号杀死时不会,所以重启前需要先清理残留文件,或者配合优雅关机。</p>')],
    steps,
    [ENV_N_GIN + '。服务端是编译好的真实二进制(自签名 ECDSA 证书在启动时生成,实验后删除),客户端用 curl 8.7.1(LibreSSL 3.3.6、nghttp2 1.69.0);每种情形各一次;handler 打印的 Proto、TLS 版本、ALPN 来自 http.Request',
     '没有验证:HTTP/2 的多路复用性能;Gin 的 HTTP/2 push 在真实浏览器里的行为(浏览器已移除);HTTP/3(QUIC);自定义 TLSConfig(如最低版本、CipherSuites,需要自己创建 http.Server);RunFd;unix socket 的权限修改(umask);h2c 的 Upgrade 路径在其它客户端里的行为'],
    'h2c、HTTP/2 与 unix socket')
